import json
def wait(i): return {"command":"wait","input":{"kind":"selector","selector":f'id="{i}"',"timeoutMs":10000}}
def press(i): return {"command":"press","input":{"target":{"kind":"selector","selector":f'id="{i}"'}}}
def is_(i,v): return {"command":"is","input":{"predicate":"text","selector":f'id="{i}"',"value":v}}
C=lambda n:f"game.cell.{n}"; S="game.status"; N="game.newGame"
def cell(n,v): return is_(C(n),v)
def status(v): return is_(S,v)
def empty_board(): return [cell(n,"Empty") for n in range(9)]
snap={"command":"snapshot","input":{}}
def play(moves): return [press(C(m)) for m in moves]
flows={}
flows["launch-empty-board"]=[wait(S),*empty_board(),status("X's turn"),snap]
flows["alternate-turns"]=[wait(S),status("X's turn"),press(C(0)),cell(0,"X"),status("O's turn"),
  press(C(4)),cell(4,"O"),status("X's turn"),press(C(0)),cell(0,"X"),status("X's turn"),snap]
flows["win-lines"]=[wait(S),*play([0,3,1,4,2]),cell(0,"X"),cell(1,"X"),cell(2,"X"),status("X wins"),
  press(C(8)),cell(8,"Empty"),status("X wins"),snap,
  press(N),status("X's turn"),*play([0,3,1,4,8,5]),cell(3,"O"),cell(4,"O"),cell(5,"O"),status("O wins"),snap]
flows["draw"]=[wait(S),*play([0,1,2,4,3,5,7,6,8]),
  *[cell(n,"X") for n in (0,2,3,7,8)],*[cell(n,"O") for n in (1,4,5,6)],status("Draw"),snap]
flows["new-game"]=[wait(S),*play([0,4,8]),cell(0,"X"),cell(4,"O"),status("O's turn"),press(N),
  *empty_board(),status("X's turn"),press(C(2)),cell(2,"X"),status("O's turn"),snap]
for k,v in flows.items():
  open(f"{k}.flow.json","w").write("[\n"+",\n".join(" "+json.dumps(s) for s in v)+"\n]\n")
EOF
